custom_css:
/* 隐藏滚动条 */
::-webkit-scrollbar {
  display: none;
}

/* 头像 */
.avatar img {
  border: none;
}


/* --- 聊天界面 --- */
#sheld {
  height: calc(100dvh - var(--topBarBlockSize));
  max-height: calc(100dvh - var(--topBarBlockSize));
}

#chat {
  align-items: center;
}

/* 气泡 */
#chat .mes {
  flex-direction: column;
  align-items: center;
  width: 92%;
  top: 30px;
  margin-bottom: 60px;
  border-radius: 2px;
  box-shadow: 0 0 4px #E5E5E5 !important;
}

/* 头像 */
.mesAvatarWrapper {
  transform: none !important;
}

.mes .avatar {
  position: absolute;
  top: 20px;
  left: -12px;
  --avatar-base-height: 60px;
  --avatar-base-width: 60px;
}

.mes .avatar img {
  border: 1px solid var(--SmartThemeBorderColor);
  box-shadow: 0 0 5px #BEBEBE !important;
}

/* 楼层、倒计时、词符 */
.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
  position: absolute;
  top: 52px;
  font-size: calc(var(--mainFontSize) * 0.8);
}

.mesIDDisplay {
  left: 62px;
}

.mes_timer {
  left: 92px;
}

.tokenCounterDisplay {
  left: 140px;
}

.mes[is_user="true"] .tokenCounterDisplay {
  left: 85px;
}

/* 时间戳 */
.timestamp {
  position: absolute;
  top: 70px;
  left: 62px;
}

/* 消息块 */
.mes_block:not(.mes.smallSysMes .mes_block) {
  padding-top: 20px;
  padding-right: 2px;
  transform: none !important;
}

.mes_block .ch_name:not(.mes_text) {
  padding-left: 42px;
  padding-bottom: 40px;
}

/* 消息 */
.mes_text {
  padding-right: 8px;
  text-align: justify;
}

.lastInContext {
  border-top: none !important;
}

/* 代码块 */
pre code:not(.img_enlarged_container pre code) {
  background-color: #fff !important;
  color: #7A7A7A !important;
  padding-top: 25px !important;
  line-height: 1.6;
  border-radius: 2px;
  border: 1.5px solid #F0F0F0;
  position: relative;
}

pre code:not(.img_enlarged_container pre code)::before {
  content: "code";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  width: 100%;
  height: 18px;
  padding: 1px 12px;
  background-color: #EFEFEF;
  border-bottom: 2px solid #F0F0F0;
}

pre code .fa-copy:not(.img_enlarged_container pre code .fa-copy) {
  position: absolute;
  top: -4px;
}

.img_enlarged_container pre code {
  border: none;
}

/* 分割线 */
hr {
  background-image: linear-gradient(90deg, var(--transparent), #CECECE, var(--transparent));
}

/* 最后一条消息 */
.last_mes {
  margin-bottom: 75px !important;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0;
}


/* --- 移动端 --- */
@media (max-width: 768px) {
  textarea,
  #send_textarea {
    resize: none;
  }
}
